mapper.select:
/* selectMasterMdCtBuyerProfileList */ SELECT A.ORG_CODE, A.ORG_NAME, A.STATUS, A.CONTRACT_FIRST_DATE, A.CONTRACT_START_DATE, A.CONTRACT_END_DATE, A.CONTRACT_VALIDITY_DATE, A.CONTRACT_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='CTTP' AND CODE = A.CONTRACT_TYPE) AS CONTRACT_TYPE_TEXT, A.CONTRACT_NOTE, A.CONTRACT_IMAGE_KEY, DECODE(TRIM(A.CONTRACT_IMAGE_KEY), '', 0, 1) AS CONTRACT_IMAGE_KEY_IMG, A.SALES_MAP_IMAGE_DIR, A.SALES_MAP_IMAGE_NAME, DECODE(TRIM(A.SALES_MAP_IMAGE_NAME), '', 0, 1) AS SALES_MAP_IMAGE_KEY_IMG, A.ORG_CHART_IMAGE_DIR, A.ORG_CHART_IMAGE_NAME, DECODE(TRIM(A.ORG_CHART_IMAGE_NAME), '', 0, 1) AS ORG_CHART_IMAGE_KEY_IMG, A.SYS_PROCESS_IMAGE_DIR, A.SYS_PROCESS_IMAGE_NAME, DECODE(TRIM(A.SYS_PROCESS_IMAGE_NAME), '', 0, 1) AS SYS_PROCESS_IMAGE_KEY_IMG, A.PAR_AMOUNT, A.RE_CONTRACT_START_DATE, A.RE_CONTRACT_END_DATE, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD HH24:MI:SS') AS ADD_DATE, A.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, TO_CHAR(A.CHANGE_DATE, 'YYYY/MM/DD HH24:MI:SS') AS CHANGE_DATE, A.CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME, A.PROCESS_STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='PFST' AND CODE=A.PROCESS_STATUS AND FLAG='Y') AS PROCESS_STATUS_TEXT, A.CONTRACT_KIND, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='PFST' AND CODE=A.CONTRACT_KIND AND FLAG='Y') AS CONTRACT_KIND_TEXT FROM KEP_BUYER_ORG_MNG A WHERE 1=1 AND A.STATUS <> 'D'
AND A.ORG_NAME LIKE '%' || #{st_org_name} || '%'
ORDER BY A.ORG_CODE

mapper.update:

/* deleteMasterMdCtBuyerProfile */
UPDATE	KEP_BUYER_ORG_MNG					
SET		STATUS = 'D',
		CHANGE_USER_ID = #{st_user_id},
		CHANGE_DATE = SYSDATE
WHERE	ORG_CODE = #{ORG_CODE}
